mapper.select:
SELECT U.USERNAME , U.DATA_STATUS , U.CREATED_BY , U.CREATED_AT , U.UPDATED_BY , U.UPDATED_AT FROM TB_USER U WHERE TRUE
AND U.USERNAME = #{username}
AND EXISTS ( SELECT 1 FROM TB_USER_AUTHORITY UA WHERE UA.USERNAME = U.USERNAME AND UA.AUTHORITY_ROLE = #{authorityRole} )
AND U.DATA_STATUS = #{dataStatus}
ORDER BY U.USERNAME

mapper.insert:
INSERT INTO TB_USER (
    USERNAME
  , PASSWORD
  , DATA_STATUS
  , CREATED_BY
  , UPDATED_BY
) VALUES (
    #{username}
  , #{password}
  , #{dataStatus}
  , #{author}
  , #{author}
)

mapper.update:
UPDATE TB_USER
   SET UPDATED_BY  = #{author}
     , UPDATED_AT  = NOW()

     , DATA_STATUS = #{dataStatus}


     , PASSWORD    = #{password}

 WHERE USERNAME    = #{username}
